import { useState, type ReactElement } from "react";
import JsonDslPreview, { previewSections, type PreviewSection } from "../../components/Projects/JsonDslPreview";
import { PreviewFrame } from "../components/PreviewFrame";
import { ProjectHeader } from "../components/ProjectHeader";
import { portfolioData } from "../data";

export function LibraryProjectSection({ embedded = false }: { embedded?: boolean }): ReactElement {
  const detail = <LibraryDetail />;

  if (embedded) {
    return <div className="library-detail-panel">{detail}</div>;
  }

  return (
    <section className="section project-section project-featured" id="library">
      <ProjectHeader
        eyebrow="Project 01 · 반복 업무 화면 공통화"
        title={portfolioData.libraryProject.title}
        description={portfolioData.libraryProject.subtitle}
      />
      {detail}
    </section>
  );
}

