import { useEffect, type ReactElement } from "react";
import { PROJECTS_SCROLL_STORAGE_KEY, SITE_TITLE } from "../constants";
import { portfolioData } from "../data";
import { CareerSection } from "../sections/CareerSection";
import { HeroSection } from "../sections/HeroSection";
import { ProjectsSection } from "../sections/ProjectsSection";
import { SkillsSection } from "../sections/SkillsSection";

export function HomePage(): ReactElement {
  useEffect(() => {
    document.title = SITE_TITLE;
  }, []);

  useEffect(() => {
    const savedScrollY = sessionStorage.getItem(PROJECTS_SCROLL_STORAGE_KEY);
    if (savedScrollY === null) return;
    sessionStorage.removeItem(PROJECTS_SCROLL_STORAGE_KEY);
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        window.scrollTo(0, Number(savedScrollY));
      });
    });
  }, []);

  return (
    <main>
      <HeroSection />
      <ProjectsSection />
      <CareerSection />
      <SkillsSection />
      <footer className="site-footer">
        <span>{portfolioData.profile.name}</span>
        <a href={`mailto:${portfolioData.profile.email}`}>{portfolioData.profile.email}</a>
        <a href={portfolioData.profile.blogHref || "#hero"}>블로그</a>
        <a href="#hero">맨 위로</a>
      </footer>
    </main>
  );
}
