import type { ReactNode } from "react";
import type { ProjectId } from "./types";
import { E2EProjectSection } from "./sections/E2EProjectSection";
import { LibraryProjectSection } from "./sections/LibraryProjectSection";
import { MappingProjectSection } from "./sections/MappingProjectSection";
import { MonitoringProjectSection } from "./sections/MonitoringProjectSection";

// 프로젝트 상세 페이지 라우팅 매핑 (data.ts는 데이터만 다루므로 라우팅/렌더링 요소는 여기서 관리)
export const projectSlugById: Partial<Record<ProjectId, string>> = {
  library: "library",
  "mapping-editor": "editor",
  "monitoring-dashboard": "dashboard",
  e2e: "e2e",
};

export const projectIdBySlug: Partial<Record<string, ProjectId>> = Object.fromEntries(
  Object.entries(projectSlugById).map(([id, slug]) => [slug, id as ProjectId]),
);

export const projectDetailContentById: Partial<Record<ProjectId, ReactNode>> = {
  library: <LibraryProjectSection />,
  "mapping-editor": <MappingProjectSection />,
  "monitoring-dashboard": <MonitoringProjectSection />,
  e2e: <E2EProjectSection />,
};
