import { useEffect, type ReactElement } from "react";
import { ArrowLeft, ArrowRight } from "lucide-react";
import { Link, useParams } from "react-router-dom";
import { SITE_TITLE } from "../constants";
import { portfolioData } from "../data";
import { projectDetailContentById, projectIdBySlug, projectSlugById } from "../projectRoutes";

export function ProjectDetailPage(): ReactElement {
  const { slug } = useParams<{ slug: string }>();
  const projectId = slug ? projectIdBySlug[slug] : undefined;
  const projectIndex = projectId
    ? portfolioData.projectHighlights.findIndex((item) => item.id === projectId)
    : -1;
  const project = projectIndex >= 0 ? portfolioData.projectHighlights[projectIndex] : undefined;
  const prevProject = projectIndex > 0 ? portfolioData.projectHighlights[projectIndex - 1] : undefined;
  const nextProject =
    projectIndex >= 0 && projectIndex < portfolioData.projectHighlights.length - 1
      ? portfolioData.projectHighlights[projectIndex + 1]
      : undefined;

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [projectId]);

  useEffect(() => {
    document.title = project ? `${project.title} · ${SITE_TITLE}` : SITE_TITLE;
    return () => {
      document.title = SITE_TITLE;
    };
  }, [project]);

  return (
    <main className="project-detail-page">
      <div className="project-detail-nav">
        <Link className="text-button project-detail-back" to="/">
          <ArrowLeft size={16} aria-hidden="true" /> 목록으로
        </Link>
      </div>
      {project && projectId ? (
        <>
          {projectDetailContentById[projectId]}
          <div className="project-detail-footer-nav">
            {prevProject ? (
              <Link className="project-detail-footer-link prev" to={`/projects/${projectSlugById[prevProject.id]}`}>
                <ArrowLeft size={16} aria-hidden="true" />
                <span>
                  <small>이전 프로젝트</small>
                  <strong>{prevProject.title}</strong>
                </span>
              </Link>
            ) : (
              <span />
            )}
            {nextProject ? (
              <Link className="project-detail-footer-link next" to={`/projects/${projectSlugById[nextProject.id]}`}>
                <span>
                  <small>다음 프로젝트</small>
                  <strong>{nextProject.title}</strong>
                </span>
                <ArrowRight size={16} aria-hidden="true" />
              </Link>
            ) : (
              <Link className="project-detail-footer-link next emphasis" to="/">
                <span>
                  <small>마지막 프로젝트입니다</small>
                  <strong>목록으로 돌아가기</strong>
                </span>
                <ArrowRight size={16} aria-hidden="true" />
              </Link>
            )}
          </div>
        </>
      ) : (
        <p className="project-detail-not-found">존재하지 않는 프로젝트입니다.</p>
      )}
    </main>
  );
}
