import type { ReactElement, ReactNode } from "react";
import { ArrowRight, Check } from "lucide-react";
import { Link } from "react-router-dom";
import { SectionHeader } from "../components/SectionHeader";
import { PROJECTS_SCROLL_STORAGE_KEY } from "../constants";
import { portfolioData } from "../data";
import { projectSlugById } from "../projectRoutes";
import type { ProjectHighlight, ProjectId } from "../types";
import mappingEditorOverview from "../../assets/img/mapping-editor-overview.png";
import dashboardOverview from "../../assets/img/dashboard-overview.png";

// 프로젝트 id별 카드 미리보기 콘텐츠 (data.ts는 데이터만 다루므로 렌더링 요소는 여기서 매핑)
const overviewByProjectId: Partial<Record<ProjectId, ReactNode>> = {
  "mapping-editor": (
    <section className="mapping-summary" aria-label="담당 범위">
      <img src={mappingEditorOverview} alt="Mapping Editor 프로젝트 핵심 구조" className="mapping-summary-overview" />
    </section>
  ),
  "monitoring-dashboard": (
    <section className="dashboard-scope" aria-label="담당 범위">
      <img src={dashboardOverview} alt="모니터링 대시보드" className="mapping-summary-overview" />
    </section>
  ),
};

type RenderedProject = ProjectHighlight & {
  overview?: ReactNode;
};

export function ProjectsSection(): ReactElement {
  const projectSummaries: RenderedProject[] = portfolioData.projectHighlights.map((project) => ({
    ...project,
    overview: overviewByProjectId[project.id],
  }));

  return (
    <section className="section" id="projects">
      <SectionHeader
        eyebrow="Projects"
      />
      <div className="project-showcase-list">
        {projectSummaries.map((project) => (
          <ProjectSummaryCard project={project} key={project.href} />
        ))}
      </div>
    </section>
  );
}

function ProjectSummaryCard({ project }: { project: RenderedProject }): ReactElement {
  const slug = projectSlugById[project.id];
  const to = slug ? `/projects/${slug}` : project.href;

  const handleClick = (): void => {
    sessionStorage.setItem(PROJECTS_SCROLL_STORAGE_KEY, String(window.scrollY));
  };

  return (
    <Link className="project-summary-card" id={project.id} to={to} onClick={handleClick}>
      <div className="project-summary-main">
        <div className="project-summary-copy">
          <div className="project-kicker">
            <span>{project.number}</span>
            <small>{project.shortName}</small>
          </div>
          <h3>{project.title}</h3>
          <p>{project.subTitle ?? project.text}</p>
          <div className="tag-list">
            {project.tags.map((tag) => <span key={tag}>{tag}</span>)}
          </div>
          {project.overview}
          {(project.contribution || project.outcome) && (
            <>
              <dl className="restored-summary-points">
                {project.contribution && (
                  <div className="project-contribution-row">
                    <ul className="project-contribution-list">
                      {project.contribution.map((item) => (
                        <li key={item.title + item.highlight}>
                          <p className="contribution-title">{item.title}</p>
                          <p className="contribution-text">
                            {item.text}
                            <strong className="contribution-highlight">{item.highlight}</strong>
                          </p>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </dl>
              {project.outcome && (
                <div className="project-outcome-row">
                  <span className="project-outcome-box">
                    <span className="project-outcome-icon">
                      <Check size={16} aria-hidden="true" />
                    </span>
                    <span className="project-outcome-text">
                      {project.outcome.text}
                      <strong className="project-outcome-highlight">{project.outcome.highlight}</strong>
                    </span>
                  </span>
                </div>
              )}
            </>
          )}
        </div>
        {project.timeline && <ProjectSummaryTimeline items={project.timeline} />}
        <span className="text-button">
          {project.cta} <ArrowRight size={16} aria-hidden="true" />
        </span>
      </div>
    </Link>
  );
}

function ProjectSummaryTimeline({ items }: { items: NonNullable<ProjectHighlight["timeline"]> }): ReactElement {
  return (
    <ol className="project-summary-timeline" aria-label="프로젝트 흐름 요약">
      {items.map((item) => (
        <li className="project-summary-timeline-item" key={`${item.label}-${item.title}`}>
          <span>{item.label}</span>
          <h4>{item.title}</h4>
          <p>{item.text}</p>
          <strong>{item.outcome}</strong>
        </li>
      ))}
    </ol>
  );
}
