import type { ReactElement, ReactNode } from "react";

export function SectionHeader({
  eyebrow,
  title,
  description,
}: {
  eyebrow: string;
  title?: ReactNode;
  description?: ReactNode;
}): ReactElement {
  return (
    <div className="section-header">
      <p className="eyebrow">{eyebrow}</p>
      {title && <h2>{title}</h2>}
      {description && <p>{description}</p>}
    </div>
  );
}
