import { useState, type ReactElement } from "react";
import { Moon, Sun } from "lucide-react";
import { Route, Routes } from "react-router-dom";
import "./App.css";
import { portfolioData } from "./portfolio/data";
import { HomePage } from "./portfolio/pages/HomePage";
import { ProjectDetailPage } from "./portfolio/pages/ProjectDetailPage";
import type { ThemeMode } from "./portfolio/types";

function App(): ReactElement {
  const [theme, setTheme] = useState<ThemeMode>("light");

  return (
    <div className="portfolio" data-theme={theme}>
      <header className="site-header">
        <a className="brand" href="/#hero" aria-label="포트폴리오 첫 화면으로 이동">
          {portfolioData.profile.name}
        </a>
        <nav className="desktop-nav" aria-label="주요 섹션">
          {portfolioData.navigation.map(([id, label]) => (
            <a key={id} href={`/#${id}`}>
              {label}
            </a>
          ))}
        </nav>
        <button
          className="icon-button"
          type="button"
          aria-label="테마 변경"
          onClick={() => setTheme((value) => (value === "light" ? "dark" : "light"))}
        >
          {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
        </button>
      </header>

      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/projects/:slug" element={<ProjectDetailPage />} />
      </Routes>
    </div>
  );
}

export default App;
